<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { api, post } from '../api'
import LegacyIcon from './LegacyIcon.vue'
interface EngineMeta { id: string; name: string; description: string; needs_local_models: boolean; available: boolean }
interface Readiness { ready: boolean; reason: string; message: string }
interface Payload { engine: string; image_description_model?: { profile_id: string; model_id: string } | null; engines: Record<string, Record<string, any>>; available_engines: EngineMeta[]; readiness: Record<string, Readiness>; installable: string[]; mineru: { api_token_set: boolean; local_cli?: unknown }; docling?: { api_token_set: boolean } }
interface ModelOption { profile_id: string; model_id: string; profile_name: string; model_name: string; supports_vision?: boolean }
const props = withDefaults(defineProps<{ pending?: unknown; revision?: number }>(), { revision: 0 })
const emit = defineEmits<{ change: [value: Payload]; loaded: [value: Payload]; engineChange: [value: string] }>()
const data = reactive<Payload>({ engine: 'text_only', image_description_model: null, engines: {}, available_engines: [], readiness: {}, installable: [], mineru: { api_token_set: false } })
const models = ref<ModelOption[]>([])
const loading = ref(true)
const error = ref('')
const testing = ref(false)
const testResult = ref<{ ok: boolean; message: string } | null>(null)
const job = ref<{ kind: string; state: string; lines: string[]; message: string } | null>(null)
const doclingTokenTouched = ref(false)
let jobTimer: ReturnType<typeof setInterval> | undefined
let cursor = 0
const selectedModel = computed({ get: () => data.image_description_model ? JSON.stringify([data.image_description_model.profile_id, data.image_description_model.model_id]) : '', set: value => { const model = models.value.find(item => JSON.stringify([item.profile_id, item.model_id]) === value); data.image_description_model = model ? { profile_id: model.profile_id, model_id: model.model_id } : null; changed() } })
const missingModel = computed(() => data.image_description_model && !models.value.some(item => item.profile_id === data.image_description_model?.profile_id && item.model_id === data.image_description_model?.model_id))
const currentSlice = computed(() => data.engines[data.engine] || {})
const currentAvailable = computed(() => data.available_engines.find(engine => engine.id === data.engine)?.available ?? false)
const descriptions: Record<string, string> = {
  text_only: '内置纯文本提取，支持 PDF、Office 和文本文件，不需要可选解析包、模型下载或布局重建。',
  mineru: '高保真多模态解析，支持布局、表格和公式。可使用本地 CLI 或云端 API。',
  docling: '结构化文档转换，支持布局与表格。可使用本地 docling 包或远程 Docling Serve。',
  markitdown: '轻量、无需下载模型，支持多种格式并输出 Markdown。',
  pymupdf4llm: '轻量、无需模型或 CUDA，适合低配置机器，将 PDF/电子书转换为 Markdown。',
  liteparse: 'LlamaIndex 的快速轻量 PDF 解析器，支持空间文本提取和可选图片提取。',
  tika: '连接远程 Apache Tika 服务，支持多种格式，无需本地安装或模型。',
}
function assign(next: Payload) { Object.assign(data, next); data.engines = next.engines || {}; data.available_engines = next.available_engines || []; data.readiness = next.readiness || {}; data.installable = next.installable || [] }
async function load() { loading.value = true; error.value = ''; try { const [live, options] = await Promise.all([api<Payload>('/api/settings/document-parsing'), api<{ options: ModelOption[] }>('/api/settings/llm-options').catch(() => ({ options: [] }))]); assign((props.pending as Payload | undefined) ?? live); models.value = options.options.filter(model => model.supports_vision); emit('loaded', live); emit('engineChange', data.engine) } catch (cause) { error.value = cause instanceof Error ? cause.message : '文档解析设置加载失败' } finally { loading.value = false } }
onMounted(load); watch(() => props.revision, load); onUnmounted(() => { if (jobTimer) clearInterval(jobTimer) })
function changed() { emit('change', JSON.parse(JSON.stringify(data))) }
function patch(body: Record<string, unknown>) { for (const [key, value] of Object.entries(body)) { if (key === 'engines') { for (const [engine, patch] of Object.entries(value as Record<string, Record<string, unknown>>)) data.engines[engine] = { ...data.engines[engine], ...patch } } else (data as unknown as Record<string, unknown>)[key] = value }; changed() }
function selectEngine(id: string) { if (data.engine === id) return; testResult.value = null; patch({ engine: id }); emit('engineChange', id) }
function patchEngine(changes: Record<string, unknown>) { patch({ engines: { [data.engine]: changes } }) }
function readiness() { return data.readiness[data.engine] }
function pipHint(engine: string) { return ({ docling: 'pip install deeptutor[parse-docling]', markitdown: 'pip install deeptutor[parse-markitdown]', pymupdf4llm: 'pip install deeptutor[parse-pymupdf4llm]', liteparse: 'pip install deeptutor[parse-liteparse]' } as Record<string, string>)[engine] || '' }
function pollJob(kind: string) { if (jobTimer) clearInterval(jobTimer); jobTimer = setInterval(async () => { try { const next = await api<{ state: string; kind?: string; lines?: string[]; next_cursor?: number; message?: string }>(`/api/settings/document-parsing/job/status?cursor=${cursor}`); if (next.kind && next.kind !== kind) return; cursor = next.next_cursor ?? cursor; if (job.value) job.value = { kind, state: next.state, lines: [...job.value.lines, ...(next.lines || [])].slice(-100), message: next.message || '' }; if (next.state !== 'running') { if (jobTimer) clearInterval(jobTimer); jobTimer = undefined; if (next.state === 'done') await load() } } catch { /* keep polling */ } }, 1000) }
async function startJob(kind: 'install' | 'models') { const url = kind === 'install' ? '/api/settings/document-parsing/install' : '/api/settings/document-parsing/models/download'; try { const result = await post<{ ok: boolean; message?: string; detail?: string }>(url, { engine: data.engine }); if (!result.ok) { job.value = { kind, state: 'failed', lines: [], message: result.message || result.detail || '操作失败' }; return }; cursor = 0; job.value = { kind, state: 'running', lines: [], message: '' }; pollJob(kind) } catch (cause) { job.value = { kind, state: 'failed', lines: [], message: cause instanceof Error ? cause.message : '操作失败' } }
}
async function cancelJob() { await post('/api/settings/document-parsing/job/cancel', {}).catch(() => null) }
async function testConnection() { testing.value = true; testResult.value = null; try { const slice = currentSlice.value; const body = data.engine === 'tika' ? { server_url: String(slice.server_url || 'http://localhost:9998').trim() } : { api_base_url: String(slice.api_base_url || 'http://localhost:5001').trim(), ...(doclingTokenTouched.value ? { api_token: slice.api_token || '' } : {}) }; testResult.value = await post<{ ok: boolean; message: string }>(`/api/settings/document-parsing/${data.engine}/test`, body) } catch (cause) { testResult.value = { ok: false, message: cause instanceof Error ? cause.message : '连接测试失败' } } finally { testing.value = false } }
</script>
<template><div class="document-parsing-settings"><header class="legacy-settings-page-header"><h1>文档解析</h1><p>配置上传文档如何转换为知识库和题目生成所需文本。选择引擎及选项；本地模型默认不会自动下载，只有明确允许后才会下载。</p></header><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="loading" class="legacy-settings-loading">加载中…</p><template v-else><section class="document-model-select"><label for="image-description-model">图片说明模型</label><select id="image-description-model" v-model="selectedModel"><option value="">使用主 LLM（回退）</option><option v-if="missingModel" :value="selectedModel" disabled>选中的模型不可用</option><option v-for="model in models" :key="`${model.profile_id}:${model.model_id}`" :value="JSON.stringify([model.profile_id, model.model_id])">{{ model.profile_name }} / {{ model.model_name }}</option></select><p>选择用于文档图片描述的视觉模型。</p></section><section class="legacy-setting-section"><header><h2>解析引擎</h2><p>当前引擎处理全部文档。Text-only 为内置；markitdown 较轻量；MinerU 与 Docling 提供更丰富结构；Tika 提供远程文本提取。</p></header><div class="document-engine-list"><button v-for="engine in data.available_engines" :key="engine.id" :class="{ active: data.engine === engine.id }" @click="selectEngine(engine.id)"><div><div><strong>{{ engine.id === 'text_only' ? 'Text-only' : engine.name }}</strong><span v-if="data.engine === engine.id" class="document-active">当前使用</span><span v-if="!engine.available" class="document-unavailable">未安装</span></div><p>{{ descriptions[engine.id] || engine.description }}</p></div></button></div></section><section v-if="data.engine === 'text_only'" class="legacy-setting-section"><header><h2>Text-only</h2><p>内置纯文本提取，无需可选包、模型、OCR 或布局重建。</p></header><div class="document-ready"><LegacyIcon name="check" :size="14" />可以解析。</div></section><section v-else-if="!currentAvailable && ['docling', 'markitdown', 'pymupdf4llm', 'liteparse'].includes(data.engine)" class="legacy-setting-section"><header><h2>{{ data.available_engines.find(engine => engine.id === data.engine)?.name || data.engine }}</h2><p>尚未安装。安装解析包后才能使用，安装会在服务器上运行。</p></header><div class="legacy-setting-section-body"><div class="legacy-setting-row"><div><h3>安装解析包</h3><p><code>{{ pipHint(data.engine) }}</code></p></div><button class="primary" @click="startJob('install')">安装</button></div></div></section><template v-else-if="data.engine === 'docling'"><section class="legacy-setting-section"><header><h2>Docling 后端</h2><p>选择本机 docling 包或远程 Docling Serve。</p></header><div class="legacy-setting-section-body"><div class="legacy-setting-row"><div><h3>模式</h3><p>{{ currentSlice.mode === 'remote' ? '文档发送到远程 Docling Serve。' : '在本机使用已安装的 docling 包。' }}</p></div><div class="mineru-mode"><button :class="{ active: currentSlice.mode !== 'remote' }" @click="patchEngine({ mode: 'local' })">本地</button><button :class="{ active: currentSlice.mode === 'remote' }" @click="patchEngine({ mode: 'remote' })">远程服务器</button></div></div></div></section><section v-if="currentSlice.mode === 'remote'" class="legacy-setting-section"><header><h2>远程服务器</h2><p>无需本地安装 docling 或模型。</p></header><div class="legacy-setting-section-body"><div class="legacy-setting-row"><div><h3>服务器地址</h3></div><input :value="currentSlice.api_base_url || ''" class="legacy-setting-number wide" aria-label="服务器地址" placeholder="http://localhost:5001" @input="patchEngine({ api_base_url: ($event.target as HTMLInputElement).value })"></div><div class="legacy-setting-row"><div><h3>API Key</h3><p>{{ data.docling?.api_token_set ? '已保存密钥，输入以替换；留空则保留。' : '可选，以 X-Api-Key 头发送。' }}</p></div><input :value="currentSlice.api_token || ''" type="password" class="legacy-setting-number wide" placeholder="可选 API Key" @input="doclingTokenTouched = true; patchEngine({ api_token: ($event.target as HTMLInputElement).value })"></div><div class="legacy-setting-row"><div><h3>测试连接</h3><p>检查服务器健康状态与版本端点。</p></div><button :disabled="testing" @click="testConnection">{{ testing ? '测试中…' : '测试' }}</button></div></div></section><section class="legacy-setting-section"><header><h2>解析选项</h2></header><div class="legacy-setting-section-body"><div v-if="currentSlice.mode !== 'remote'" class="legacy-setting-row"><div><h3>允许自动下载模型</h3><p>默认关闭，也可使用 docling-tools 预先下载。</p></div><button role="switch" aria-label="允许自动下载模型" :aria-checked="Boolean(currentSlice.allow_local_model_download)" class="legacy-toggle" :class="{ on: currentSlice.allow_local_model_download }" @click="patchEngine({ allow_local_model_download: !currentSlice.allow_local_model_download })"><span /></button></div><div class="legacy-setting-row"><div><h3>识别表格</h3></div><button role="switch" aria-label="识别表格" :aria-checked="currentSlice.do_table_structure !== false" class="legacy-toggle" :class="{ on: currentSlice.do_table_structure !== false }" @click="patchEngine({ do_table_structure: currentSlice.do_table_structure === false })"><span /></button></div><div class="legacy-setting-row"><div><h3>OCR 扫描页</h3><p>速度较慢，适用于纯图片 PDF。</p></div><button role="switch" aria-label="OCR 扫描页" :aria-checked="Boolean(currentSlice.do_ocr)" class="legacy-toggle" :class="{ on: currentSlice.do_ocr }" @click="patchEngine({ do_ocr: !currentSlice.do_ocr })"><span /></button></div></div></section><div v-if="readiness() && currentSlice.mode !== 'remote'" class="document-readiness" :class="{ ready: readiness().ready }">{{ readiness().ready ? '可以解析。' : readiness().message }}<button v-if="!readiness().ready" @click="startJob('models')">下载模型</button></div></template><section v-else-if="data.engine === 'tika'" class="legacy-setting-section"><header><h2>Tika</h2><p>连接 Apache Tika 服务器，无需本地安装或模型。</p></header><div class="legacy-setting-section-body"><div class="legacy-setting-row"><div><h3>服务器地址</h3></div><input :value="currentSlice.server_url || ''" class="legacy-setting-number wide" aria-label="服务器地址" placeholder="http://localhost:9998" @input="patchEngine({ server_url: ($event.target as HTMLInputElement).value })"></div><div class="legacy-setting-row"><div><h3>测试连接</h3><p>请求服务器 /version 端点。</p></div><button :disabled="testing" @click="testConnection">{{ testing ? '测试中…' : '测试' }}</button></div><div v-if="readiness()" class="document-readiness" :class="{ ready: readiness().ready }">{{ readiness().ready ? '可以解析。' : readiness().message }}</div></div></section><section v-else-if="data.engine === 'markitdown'" class="legacy-setting-section"><header><h2>markitdown</h2><p>轻量 Markdown 转换，无需模型下载。</p></header><div class="legacy-setting-section-body"><div class="legacy-setting-row"><div><h3>使用视觉模型描述图片</h3><p>转换时调用 DeepTutor 的视觉模型生成图片说明。</p></div><button role="switch" aria-label="使用视觉模型描述图片" :aria-checked="Boolean(currentSlice.enable_llm_image_description)" class="legacy-toggle" :class="{ on: currentSlice.enable_llm_image_description }" @click="patchEngine({ enable_llm_image_description: !currentSlice.enable_llm_image_description })"><span /></button></div></div></section><section v-else-if="data.engine === 'pymupdf4llm'" class="legacy-setting-section"><header><h2>PyMuPDF4LLM</h2><p>轻量 PDF/电子书转 Markdown，无需模型或 CUDA。</p></header><div class="legacy-setting-section-body"><div class="legacy-setting-row"><div><h3>提取图片</h3><p>保存嵌入图片和渲染的矢量图，并在 Markdown 中引用。</p></div><button role="switch" aria-label="提取图片" :aria-checked="currentSlice.write_images !== false" class="legacy-toggle" :class="{ on: currentSlice.write_images !== false }" @click="patchEngine({ write_images: currentSlice.write_images === false })"><span /></button></div><template v-if="currentSlice.write_images !== false"><div class="legacy-setting-row"><div><h3>图片格式</h3></div><select :value="currentSlice.image_format || 'png'" @change="patchEngine({ image_format: ($event.target as HTMLSelectElement).value })"><option value="png">png</option><option value="jpg">jpg</option><option value="jpeg">jpeg</option><option value="webp">webp</option></select></div><div class="legacy-setting-row"><div><h3>图片分辨率（DPI）</h3><p>越高越清晰，但文件更大，范围 72–600。</p></div><input :value="currentSlice.image_dpi || 150" class="legacy-setting-number" type="number" min="72" max="600" @input="patchEngine({ image_dpi: Number(($event.target as HTMLInputElement).value) })"></div></template></div></section><section v-else-if="data.engine === 'liteparse'" class="legacy-setting-section"><header><h2>LiteParse</h2><p>LlamaIndex 的快速 PDF/Office/图片解析器，无需模型下载。</p></header><div class="legacy-setting-section-body"><div class="legacy-setting-row"><div><h3>图片模式</h3><p>控制输出中图片的表示方式。</p></div><select :value="currentSlice.image_mode || 'placeholder'" @change="patchEngine({ image_mode: ($event.target as HTMLSelectElement).value })"><option value="placeholder">placeholder</option><option value="off">off</option><option value="embed">embed</option></select></div><div class="legacy-setting-row"><div><h3>提取链接</h3><p>输出 Markdown 的 [文字](URL) 链接。</p></div><button role="switch" aria-label="提取链接" :aria-checked="currentSlice.extract_links !== false" class="legacy-toggle" :class="{ on: currentSlice.extract_links !== false }" @click="patchEngine({ extract_links: currentSlice.extract_links === false })"><span /></button></div><div class="legacy-setting-row"><div><h3>提取图片</h3><p>将嵌入图片与解析后的 Markdown 一并保存。</p></div><button role="switch" aria-label="提取图片" :aria-checked="Boolean(currentSlice.extract_images)" class="legacy-toggle" :class="{ on: currentSlice.extract_images }" @click="patchEngine({ extract_images: !currentSlice.extract_images })"><span /></button></div><div class="legacy-setting-row"><div><h3>最大页数</h3><p>0 表示不限制每份文档的解析页数。</p></div><input :value="currentSlice.max_pages || 0" class="legacy-setting-number" type="number" min="0" @input="patchEngine({ max_pages: Number(($event.target as HTMLInputElement).value) })"></div></div></section><div v-if="testResult" class="document-test-result" :class="testResult.ok ? 'ok' : 'bad'">{{ testResult.message }}</div><div v-if="job" class="document-job" :class="job.state"><div><p>{{ job.state === 'running' ? '正在执行…' : job.message || job.state }}</p><button v-if="job.state === 'running'" @click="cancelJob">取消</button></div><pre v-if="job.lines.length">{{ job.lines.join('\n') }}</pre></div></template></div></template>
